<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
class PracticePlanningController extends Controller{
private function manage(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('academic_head')||$r->user()->hasRole('practice_head')||$r->user()->canDo('practice.manage'),403);}
public function annual(Request $r){$this->manage($r);$p=$r->attributes->get('academic_period');$rows=DB::table('practice_campaigns as c')->join('study_groups as g','g.id','=','c.study_group_id')->leftJoin('teachers as t','t.id','=','c.supervisor_teacher_id')->where('c.academic_period_id',$p->id)->select('c.*','g.name group_name','t.last_name teacher_name')->orderBy('c.starts_on')->get();return view('practice-office.annual',compact('rows','p'));}
public function visits(Request $r){$this->manage($r);$p=$r->attributes->get('academic_period');$rows=DB::table('practice_control_visits as v')->join('practice_placements as pp','pp.id','=','v.practice_placement_id')->join('students as s','s.id','=','pp.student_id')->leftJoin('teachers as t','t.id','=','v.teacher_id')->where('pp.academic_period_id',$p->id)->select('v.*','s.last_name','s.first_name','pp.organization_name','t.last_name teacher_name')->orderByDesc('v.visited_at')->get();return view('practice-office.visits',compact('rows'));}
public function results(Request $r){$this->manage($r);$p=$r->attributes->get('academic_period');$rows=DB::table('practice_placements as pp')->join('students as s','s.id','=','pp.student_id')->leftJoin('study_groups as g','g.id','=','s.current_group_id')->leftJoin('practice_employment_results as e','e.practice_placement_id','=','pp.id')->where('pp.academic_period_id',$p->id)->select('pp.*','s.last_name','s.first_name','g.name group_name','e.status employment_status','e.position','e.employment_on')->orderBy('g.name')->orderBy('s.last_name')->get();return view('practice-office.results',compact('rows'));}
public function employment(Request $r,$placement){$this->manage($r);$d=$r->validate(['status'=>'required|in:offered,employed,declined,not_offered,unknown','position'=>'nullable|string|max:255','employment_on'=>'nullable|date','note'=>'nullable|string|max:3000']);DB::table('practice_employment_results')->updateOrInsert(['practice_placement_id'=>$placement],$d+['recorded_by'=>$r->user()->id,'updated_at'=>now(),'created_at'=>now()]);return back();}
public function partnerAccess(Request $r,$organization){$this->manage($r);abort_unless(DB::table('practice_organizations')->where('id',$organization)->exists(),404);$token=Str::random(56);DB::table('practice_partner_access')->where('practice_organization_id',$organization)->update(['active'=>0,'updated_at'=>now()]);DB::table('practice_partner_access')->insert(['practice_organization_id'=>$organization,'token'=>$token,'expires_at'=>now()->addMonths(6),'active'=>1,'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back()->with('partner_url',route('practice.partner',['token'=>$token]));}
public function massDocument(Request $r,$campaign){$this->manage($r);$c=DB::table('practice_campaigns')->find($campaign);abort_if(!$c,404);$d=$r->validate(['type'=>'required|in:directions,order','number'=>'required|string|max:100','document_on'=>'required|date']);$placements=DB::table('practice_placements as p')->join('students as s','s.id','=','p.student_id')->where('p.practice_campaign_id',$campaign)->select('p.*','s.last_name','s.first_name','s.middle_name')->get();abort_if($placements->isEmpty(),422,'Нет распределённых студентов');$id=DB::table('practice_mass_documents')->insertGetId(['practice_campaign_id'=>$campaign,'type'=>$d['type'],'number'=>$d['number'],'document_on'=>$d['document_on'],'snapshot_json'=>json_encode(['campaign'=>$c,'placements'=>$placements],JSON_UNESCAPED_UNICODE),'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return redirect()->route('practice-office.mass.print',$id);}
public function massPrint(Request $r,$id){$this->manage($r);$doc=DB::table('practice_mass_documents')->find($id);abort_if(!$doc,404);$data=json_decode($doc->snapshot_json);return view('practice-office.mass-print',compact('doc','data'));}
}